MovingForward.RowColumnDepth:
if (Scan.IsSuspendedToWaitForClient) {
    return [];
} 

if (PixelDepth == Scan.Depths) {
    Scan.End();
    return [PixelRow, PixelColumn, PixelDepth];
}

Scan.SuspendToWaitForClient();
Scan.WaitingForward();
return [PixelRow, PixelColumn, PixelDepth];

WaitingForward.RowColumnDepth:
if (Scan.IsSuspendedToWaitForClient)
    return [];
Scan.MovingForward();
return [PixelRow, PixelColumn, PixelDepth+1];
